    /**
     * Handles loading a Team using a UUID
     * @param		UUID uuid 
     * @return		Team
     */    
    @GetMapping("/load")
    public Team load( @RequestParam(required=true) UUID uuid ) {    	
    	Team entity = null;

    	try {  
    		entity = service.getTeam( new TeamFetchOneSummary( uuid ) );   
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Team using Id " + uuid );
            return null;
        }

        return entity;
    }

